int count_guesses(int secret, int lo, int hi) {
    int guesses = 0;
    while (lo <= hi) {
        int mid = lo + (hi - lo) / 2;
        guesses++;
        if (mid == secret) {
            return guesses;
        }
        if (mid < secret) {
            lo = mid + 1;
        } else {
            hi = mid - 1;
        }
    }
    return guesses;
}

int count_guesses(int secret, int lo, int hi) {
    int guesses = 0;
    for (; lo <= hi; ) {
        int mid = lo + (hi - lo) / 2;
        guesses++;
        if (mid == secret) return guesses;
        if (mid < secret) lo = mid + 1;
        else hi = mid - 1;
    }
    return guesses;
}

int count_guesses(int secret, int lo, int hi) {
    int guesses = 0;
    while (lo <= hi) {
        int mid = (lo + hi) / 2;
        guesses = guesses + 1;
        if (mid == secret) return guesses;
        if (secret > mid) lo = mid + 1;
        else hi = mid - 1;
    }
    return guesses;
}
